package com.cloudticket.comment.client;
import java.util.Map; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.ParameterizedTypeReference; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
@Component public class OrderEligibilityClient { private final RestClient client; public OrderEligibilityClient(RestClient.Builder builder,@Value("${cloudticket.order-base-url:http://order-service:8083}") String base,@Value("${cloudticket.internal-service-token:dev-internal-token}") String token){client=builder.baseUrl(base).defaultHeader("X-Internal-Service-Token",token).build();} public boolean paid(String userId,String activityId){Map<String,Object> value=client.get().uri("/api/internal/orders/users/{u}/activities/{a}/paid",userId,activityId).retrieve().body(new ParameterizedTypeReference<>(){});return value!=null&&Boolean.TRUE.equals(value.get("eligible"));} }
